 * (data.repository.pullRequest.reviewThreads.nodes) and the short
 * ({nodes:[...]}) envelope.
 */
function envelopeReviewThreads(data) {
    return envelopeNodesAt(['data', 'repository', 'pullRequest', 'reviewThreads'], data) ||
        envelopeNodesAt(['nodes'], data) || [];
