 * Normalize the github_get_pr_review_threads return (JSON string | node
 * array | full envelope | {nodes:[...]} short envelope) into a node array.
 */
function parseGraphQLNodes(raw) {
    if (!raw) return [];
    var data = raw;
    if (typeof data === 'string') {
