        var sm = makeSmAgent(Object.assign(config('epam', 'dmtools-agents'), {
            github: {
                items: [devItem(1364, HEAD)],
                pr: { number: 1364, body: 'Closes #1363', head: { sha: HEAD } },
                prComments: [lapComment(HEAD, 1, 2)]
            }

