    sm.action(baseParams('epam', 'dmtools-agents', [sweepRule(30)], { machineAuthor: 'ai-teammate' }));
    assert.equal(sm.capturedPrLabelAdds.length, 1, 'the refresh advanced the head but the threads are still open — restore');
