                 prMachineAuthor: true, threadsResolved: false, draft: false },
        localAction: 'arm_rework',
        limit: 5,
        id: 'rework-unresolved-threads'
    };

    function devItem(n, head) {
        return { key: 'pr-' + n, labels: ['ai_pr_reviewed'], issueNumber: null,
